import React, { useState } from "react";
import { signInWithEmailAndPassword, sendPasswordResetEmail } from "firebase/auth";
import { auth, authPersistenceReady } from "../firebase/firebaseConfig";
import "./Login.css";
import { Link, useNavigate } from "react-router-dom";

const Login = () => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  
  // For forgot password flow
  const [showReset, setShowReset] = useState(false);
  const [resetEmail, setResetEmail] = useState("");
  const [resetMessage, setResetMessage] = useState("");

  const navigate = useNavigate();

  // 1) Normal login
  const handleLogin = async () => {
    console.log('🔑 handleLogin called!');
    setError("");
    try {
      console.log('🔑 Attempting to sign in with email:', email);
      console.log('🔑 Auth app name:', auth?.app?.name);
      
      // Add a timeout to prevent hanging
      // Ensure persistence is initialized (important for iOS WebView)
      await authPersistenceReady;
      console.log('🔑 Creating signInWithEmailAndPassword promise...');
      const signInPromise = signInWithEmailAndPassword(auth, email, password);
      console.log('🔑 Promise created, adding timeout...');
      
      const timeoutPromise = new Promise((_, reject) => 
        setTimeout(() => reject(new Error('Sign in timeout after 15 seconds')), 15000)
      );
      
      console.log('🔑 Racing promises...');
      await Promise.race([signInPromise, timeoutPromise]);
      console.log('🔑 Promise resolved!');
      
      console.log('🔑 Sign in successful! Navigating to /map');
      navigate("/map");
    } catch (err) {
      console.log('🔑 Sign in error:', err.code, err.message);
      setError(err.message);
    }
  };

  // 2) Forgot Password
  const handleForgotPassword = async () => {
    setError("");
    setResetMessage("");
    try {
      if (!resetEmail) {
        setError("Please enter your email to reset password");
        return;
      }
      await sendPasswordResetEmail(auth, resetEmail);
      setResetMessage(`Password reset email sent to ${resetEmail}. Please check your inbox.`);
    } catch (err) {
      setError(err.message);
    }
  };

  // 3) Close/Exit button - send user back to intro
  const handleClose = () => {
    navigate("/");
  };

  return (
    <div className="login-page">
      {/* Close Button - Top Right */}
      <button className="login-close-btn" onClick={handleClose}>
        ✕
      </button>

      <div className="login-content">
        {!showReset ? (
          // Login Form
          <div className="login-card">
            <div className="login-card-inner">
              <div className="login-header">
                <img src="/logo.png" alt="Community View Logo" className="login-logo" />
                <h1 className="login-title">Sign In</h1>
              </div>

              {error && <div className="login-error-message">{error}</div>}

              <div className="login-form">
              <div className="input-group">
                <label className="input-label">Email Address</label>
                <input
                  type="email"
                  className="login-input"
                  placeholder="Enter your email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  onKeyPress={(e) => e.key === 'Enter' && handleLogin()}
                />
              </div>

              <div className="input-group">
                <label className="input-label">Password</label>
                <input
                  type="password"
                  className="login-input"
                  placeholder="Enter your password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  onKeyPress={(e) => e.key === 'Enter' && handleLogin()}
                />
              </div>

              <button className="login-primary-btn" onClick={handleLogin}>
                Sign In
                <span className="btn-arrow">→</span>
              </button>

              <button 
                className="forgot-password-link" 
                onClick={() => setShowReset(true)}
              >
                Forgot password?
              </button>

              <div className="login-divider">
                <span>or</span>
              </div>

              <div className="signup-section">
                <p className="signup-text">Don't have an account?</p>
                <Link to="/signup" className="signup-link-btn">
                  Create Account
                </Link>
              </div>
            </div>
            </div>
          </div>
        ) : (
          // Reset Password Form
          <div className="login-card">
            <div className="login-card-inner">
              <div className="login-header">
                <img src="/logo.png" alt="Community View Logo" className="login-logo" />
                <h1 className="login-title">Reset Password</h1>
              </div>

            {error && <div className="login-error-message">{error}</div>}
            {resetMessage && <div className="login-success-message">{resetMessage}</div>}

            <div className="login-form">
              <div className="input-group">
                <label className="input-label">Email Address</label>
                <input
                  type="email"
                  className="login-input"
                  placeholder="Enter your email"
                  value={resetEmail}
                  onChange={(e) => setResetEmail(e.target.value)}
                  onKeyPress={(e) => e.key === 'Enter' && handleForgotPassword()}
                />
              </div>

              <button className="login-primary-btn" onClick={handleForgotPassword}>
                Send Reset Email
                <span className="btn-arrow">→</span>
              </button>

              <button 
                className="back-to-login-link" 
                onClick={() => setShowReset(false)}
              >
                ← Back to Sign In
              </button>
            </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Login;
